 function reset(){Object.assign(player,{x:150,y:365,vx:0,vy:0,hp:100,ground:false,jumps:0,attack:0,howl:0,dash:0,inv:0,anim:0});camera=0;gameTime=0;particles=[];shots=[];enemies=enemySeeds.map((e,i)=>({...e,hp:e.type==='guard'?3:2,alive:true,cool:45+i*9,phase:i}));enemies.push({x:4770,type:'boss',hp:24,maxHp:24,alive:true,cool:80,phase:0,w:86,h:110});ui.bossStat.style.display='none';mode='play';ui.overlay.classList.add('hidden');ui.objective.innerHTML='OBJECTIVE <b>— REACH THE EXTRACTION GATE</b>';}
-function start(){if(mode==='title'){ui.overlay.classList.add('hidden');mode='intro';player.x=150;player.y=330;setTimeout(()=>{if(mode==='intro'){burst(180,390,'#c6ff4b',34);shake=12;mode='play';ui.objective.innerHTML='OBJECTIVE <b>— ESCAPE THE FACILITY</b>'}},1100)}else if(mode==='dead'||mode==='win')reset()}
+function start(){if(mode==='title'){reset();mode='intro';player.x=190;player.y=330;setTimeout(()=>{if(mode==='intro'){burst(190,390,'#c6ff4b',34);shake=12;mode='play';ui.objective.innerHTML='OBJECTIVE <b>— ESCAPE THE FACILITY</b>'}},1100)}else if(mode==='dead'||mode==='win')reset()}
 ui.start.addEventListener('click',start);addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!keys[k]){if(k===' '||k==='w'||k==='arrowup')jump();if(k==='j'||k==='x')attack();if(k==='k'||k==='c')howl();if(k==='shift')dash()}keys[k]=true;if(k==='enter'&&(mode==='dead'||mode==='win'))start()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
 document.querySelectorAll('.touch').forEach(b=>{let k=b.dataset.key;const down=e=>{e.preventDefault();b.setPointerCapture?.(e.pointerId);keys[k]=true;if(k==='jump')jump();if(k==='attack')attack();if(k==='howl')howl();};const up=e=>{keys[k]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)});
 function jump(){if(mode!=='play')return;if(player.jumps<2){player.vy=player.jumps===0?-10.7:-9.5;player.jumps++;player.ground=false;burst(player.x,player.y+player.h,'#a4e85c',5)}}
 function attack(){if(mode!=='play'||player.attack>0)return;player.attack=15;for(const e of enemies){if(e.alive&&Math.abs(e.x-player.x)<83&&Math.abs((e.y||world.floor)-player.y)<100){e.hp-=e.type==='boss'?2:2;if(e.hp<=0){e.alive=false;burst(e.x,(e.y||world.floor)-30,e.type==='boss'?'#ff675f':'#c6ff4b',17)}else e.stun=22;shake=3}}}

